import { Box, Divider, Stack, Typography } from "@mui/material";
import React, { useEffect } from "react";
import { LoginUser, RegisterUser } from "../../redux/slices/auth";
import { useDispatch } from "react-redux";

const GoogleLogin = ({ actionType }) => {
  const dispatch = useDispatch();
  const elementId = `google-${actionType.toLowerCase()}`;

  useEffect(() => {
    let timer;
    let attempts = 0;

    const initialize = () => {
      if (!window.google?.accounts?.id) {
        if (attempts < 40) {
          attempts += 1;
          timer = window.setTimeout(initialize, 150);
        }
        return;
      }

      window.google.accounts.id.initialize({
        client_id: "396305485425-mpcokgsdtmj2btjntgh7hp1p1cbbu6po.apps.googleusercontent.com",
        context: actionType === "Login" ? "signin" : "signup",
        callback: (response) => {
          const payload = { ...response, auth_type: "GOOGLE", actionType };
          dispatch(actionType === "Login" ? LoginUser(payload) : RegisterUser(payload));
        },
        ux_mode: "popup",
        itp_support: true,
      });

      const target = document.getElementById(elementId);
      if (target) {
        target.replaceChildren();
        window.google.accounts.id.renderButton(target, {
          type: "standard",
          shape: "pill",
          theme: "outline",
          size: "large",
          text: actionType === "Login" ? "signin_with" : "signup_with",
          width: Math.min(360, Math.max(240, window.innerWidth - 82)),
        });
      }
    };

    initialize();
    return () => window.clearTimeout(timer);
  }, [actionType, dispatch, elementId]);

  return <Box id={elementId} sx={{ minHeight: 44, width: "100%", display: "flex", justifyContent: "center" }} />;
};

const AuthSocial = ({ actionType }) => (
  <Stack>
    <Divider sx={{ my: 3, color: "text.disabled", "&::before, &::after": { borderColor: "divider" } }}>
      <Typography variant="caption" color="text.secondary">or continue with</Typography>
    </Divider>
    <GoogleLogin actionType={actionType} />
  </Stack>
);

export default AuthSocial;
